{"command": "python - <<'PY'
from pathlib import Path
import re, json
root=Path('../../shared_space')
terms=['resonance','emergence','entropy','synchronization','phase','complexity','algorithm','fractal','cellular','lorenz','mandelbrot','gray','rule30','kuramoto','godel','information','computation']
files=[]
for p in root.rglob('*'):
    if p.is_file() and p.suffix.lower() in ['.md','.txt','.html','.py','.json','.csv']:
        try:
            txt=p.read_text(errors='ignore')
        except Exception:
            continue
        counts={t:len(re.findall(t, txt, flags=re.I)) for t in terms}
        score=sum(counts.values())
        if score>0:
            files.append((score,p.relative_to(root),counts))
for score,rel,counts in sorted(files, reverse=True)[:25]:
    print(f'{score:3d}\t{rel}')
    print('  ' + ', '.join(f'{k}:{v}' for k,v in counts.items() if v))
PY"}
